    [9598]={name="Sleeping Robes",sourceType="quest_reward",instructions="Reward from the quest “Druid of the Claw” — pick it over the other choices. In Teldrassil.",zone="Teldrassil",questName="Druid of the Claw",lore="After examining this charm, I see now what must be done. Please take it, and do as I ask. You are to explore the deepest areas of the Ban'ethil Barrow Den."},
    [9601]={name="Cushioned Boots",sourceType="quest_reward",instructions="Reward from the quest “Sathrah's Sacrifice” — pick it over the other choices. In Darnassus.",zone="Darnassus",questName="Sathrah's Sacrifice",lore="Now you must finish the task to which you have been appointed. Take the spinnerets and offer Lady Sathrah's sacrifice to Elune; lay the great spider to rest."},
