    [11851]={name="Scavenger Tunic",sourceType="quest_reward",instructions="Reward from the quest “Rattling the Rattlecages” — pick it over the other choices. In Deathknell.",zone="Deathknell",questName="Rattling the Rattlecages",lore="You've shown your potential to the Forsaken under normal circumstances - now let's see you under pressure. The Rattlecage skeletons, more mindless minions of the Lich King, are a tougher foe than the zombies you have faced thus far."},
